export const BODY: string = "\n<p>شعار SVG يمكن تكبيره بلا حدود، لكن كثير من الأماكن ما زالت تريد PNG. التحويل يحل المشكلة في ثوانٍ.</p>\n<p>اختر المقياس الصحيح وسيبدو PNG مثاليًا. اختر المقياس الخاطئ وسيخرج ضبابيًا أو ضخمًا.</p>\n<p>يأخذك هذا الدليل خطوة بخطوة، من رفع SVG إلى تنزيل PNG حاد.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: جهّز SVG</h2>\n<p>قبل أن تبدأ، جهّز SVG: تأكد من أن الصور مضمّنة لا مرتبطة، وأن النص محوّل إلى مسارات إذا أمكن، وأن الملف يفتح بشكل صحيح.</p>\n<p>التحضير الجيد يمنع معظم المشاكل. الملف النظيف يعطي نتيجة نظيفة.</p>\n<h2 id=\"step-1-open-tool\">الخطوة 1: افتح أداة SVG إلى PNG</h2>\n<p>افتح <a href=\"/ar/tahwil-svg-ila-png/\">أداة SVG إلى PNG</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصور إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورك خاصة طوال العملية.</p>\n<h2 id=\"step-2-upload\">الخطوة 2: ارفع ملفات SVG</h2>\n<p>ارفع ملفات SVG: أسقطها في منطقة الرفع أو اخترها من جهازك. تُقبل ملفات SVG بأي حجم معقول.</p>\n<p>إذا رفعت عدة ملفات، فستظهر كل واحدة في قائمة. يمكنك تحويلها كلها دفعة واحدة بمقياس موحد.</p>\n<h2 id=\"step-3-scale\">الخطوة 3: اختر مقياس الإخراج</h2>\n<p>اختر مقياس الإخراج: 1x للحجم الأصلي، و2x للضعف، و4x لأربعة أضعاف. المقياس يحدد حجم PNG الناتج.</p>\n<p>للأيقونات الصغيرة، استخدم 4x أو 8x. للشعارات الكبيرة، 2x كافٍ غالبًا.</p>\n<h2 id=\"step-4-convert\">الخطوة 4: حوّل الملفات</h2>\n<p>حوّل الملفات: اضغط زر التحويل وانتظر حتى تنتهي الأداة. التنقيط سريع، والدفعة المتوسطة تستغرق ثوانٍ معدودة.</p>\n<p>تابع شريط التقدم وانتظر حتى يكتمل التحويل. كل ملف يتحول على حدة، وتظهر النتائج تدريجيًا.</p>\n<h2 id=\"step-5-check\">الخطوة 5: راجع النتيجة</h2>\n<p>راجع النتيجة: افتح PNG المحوّل وكبّره وتأكد من أن الحواف حادة والنص واضح والألوان صحيحة.</p>\n<p>إذا بدت النتيجة ضبابية، فأعد التحويل بمقياس أكبر. لا تستخدم نتيجة ضبابية أبدًا.</p>\n<h2 id=\"step-6-download\">الخطوة 6: نزّل ملفات PNG</h2>\n<p>نزّل ملفات PNG: اضغط زر التنزيل واحفظ الملفات في مجلد جديد. إذا كانت عدة ملفات، فستنزّل كملف ZIP واحد.</p>\n<p>فك ضغط الملف وراجع النتائج. تحقق من أن كل ملف موجود ويبدو صحيحًا.</p>\n<ol>\n<li>ارفع ملفات SVG.</li>\n<li>اختر المقياس.</li>\n<li>حوّل الملفات.</li>\n<li>نزّل ملفات PNG.</li>\n</ol>\n<h2 id=\"converting-an-icon-pack\">تحويل حزمة أيقونات كاملة</h2>\n<p>لتحويل حزمة أيقونات كاملة، ارفع كل الملفات وحوّلها بمقياس موحد. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>استخدم المقياس نفسه لكل الأيقونات. الاتساق يجعل الحزمة تبدو احترافية وموحدة.</p>\n<h2 id=\"choosing-size-for-purpose\">اختيار الحجم لكل استخدام</h2>\n<p>لاختيار الحجم لكل استخدام، فكر في الوجهة: أيقونة موقع تحتاج إلى 32 بكسل، وشعار بطاقة يحتاج إلى 300 بكسل، ولافتة تحتاج إلى 1200 بكسل.</p>\n<p>حوّل كل حجم على حدة بمقياس مناسب. الأحجام المتعددة تضمن ظهور الصورة بشكل صحيح في كل مكان.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>لحل المشاكل الشائعة، افحص السبب أولًا. الضبابية تعني مقياسًا صغيرًا، والصورة المفقودة تعني ملفًا خارجيًا، والنص الغريب يعني خطًا غير متاح.</p>\n<p>أصلح السبب في SVG الأصلي ثم أعد التحويل. التحويل نفسه نادرًا ما يكون المشكلة.</p>\n<h2 id=\"mobile-tips\">نصائح للهواتف والأجهزة اللوحية</h2>\n<p>نصائح للهواتف والأجهزة اللوحية: افتح الأداة في المتصفح وارفع الملفات من جهازك. التحويل يعمل على الهاتف دون تثبيت أي تطبيق.</p>\n<p>للدفعات الكبيرة على الهاتف، قسّمها إلى مجموعات صغيرة. المجموعات الصغيرة أسرع وأقل عرضة للفشل.</p>\n<h2 id=\"logo-for-business-card\">تحويل شعار لبطاقة عمل</h2>\n<p>لتحويل شعار لبطاقة عمل، استخدم مقياسًا كبيرًا مثل 4x. البطاقات تُطبع بدقة عالية، والشعار الحاد يترك انطباعًا احترافيًا.</p>\n<p>اطبع من ملف PNG المحوّل. الطباعة تحتاج دقة كاملة، والمقياس الكبير يضمن حدة الطباعة.</p>\n<h2 id=\"icons-for-website\">تحويل أيقونات لموقع إلكتروني</h2>\n<p>لتحويل أيقونات لموقع إلكتروني، حوّلها بالأحجام التي يحتاجها موقعك. كل موقع يحتاج إلى أحجام أيقونات محددة.</p>\n<p>حوّل كل حجم على حدة بمقياس مناسب. الأيقونات بأحجام متعددة تضمن ظهورها بشكل صحيح في كل مكان.</p>\n<h2 id=\"svg-for-tshirt-print\">تحويل SVG لطباعة قميص</h2>\n<p>لتحويل SVG لطباعة قميص، استخدم مقياسًا كبيرًا جدًا مثل 8x. الطباعة على القماش تحتاج دقة عالية جدًا.</p>\n<p>تحقق من متطلبات المطبعة قبل التحويل. بعض المطابع تطلب أبعادًا محددة بالإضافة إلى المقياس.</p>\n<h2 id=\"svg-for-presentation\">تحويل SVG لعرض تقديمي</h2>\n<p>لتحويل SVG لعرض تقديمي، حوّلها إلى PNG بمقياس مناسب للشاشة. العروض تحتاج إلى صور حادة تبدو نظيفة على الشاشة الكبيرة.</p>\n<p>استخدم مقياس 2x لصور العروض. الجودة كافية للشاشة الكبيرة، والملف ليس ضخمًا.</p>\n<h2 id=\"svg-for-favicon\">تحويل SVG لأيقونة مفضلة</h2>\n<p>لتحويل SVG لأيقونة مفضلة، حوّلها بالأحجام التي يحتاجها المتصفح: 16 و32 و48 بكسل. الأيقونة المفضلة تظهر في علامات التبويب والإشارات.</p>\n<p>حوّل كل حجم على حدة بمقياس مناسب. الأحجام المتعددة تضمن ظهور الأيقونة بشكل صحيح في كل مكان.</p>\n<h2 id=\"svg-for-website-banner\">تحويل SVG للافتة موقع</h2>\n<p>لتحويل SVG للافتة موقع، استخدم مقياسًا كبيرًا مثل 4x. اللافتة تملأ عرض الصفحة، والجودة العالية تمنع التشوهات.</p>\n<p>وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-svg-ila-png/\">الدليل الكامل لتحويل SVG إلى PNG</a> و<a href=\"/ar/blog/svg-vs-png-mutajjih-wa-nuqti/\">SVG مقابل PNG: متجه ونقطي</a>، أو جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> لصيغ أخرى.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما حجم ملف PNG بمقياس 1x؟","answer":"مقياس 1x يعطي الحجم الأصلي لـSVG. إذا كان SVG بحجم 24 بكسل، فسيكون PNG بحجم 24 بكسل."},{"question":"هل يمكنني تحويل ملفات SVG على هاتفي؟","answer":"نعم، يعمل التحويل في متصفح هاتفك دون تثبيت أي تطبيق. افتح الأداة وارفع الملف وحوّله ونزّل النتيجة."},{"question":"ما اسم الملف الذي سيحتفظ به ملف PNG المصدّر؟","answer":"يحتفظ PNG بالاسم نفسه مع امتداد png بدل svg. إذا كان الملف logo.svg، فسيكون الناتج logo.png."},{"question":"هل يدعم المحول الرسوم المتحركة SVG؟","answer":"لا، المحول لا يدعم الرسوم المتحركة SVG. التحويل إلى PNG يحفظ الإطار الأول فقط ويفقد الحركة."},{"question":"هل يمكنني تنقيط SVG فيه صورة مضمّنة كـdata URI؟","answer":"نعم، يمكنك تنقيط SVG فيه صورة مضمّنة كـdata URI. الصور المضمّنة تنتقل مع الملف وتظهر في النتيجة."},{"question":"لماذا يبدو ملف PNG المحوّل ضبابيًا؟","answer":"لأن المقياس صغير جدًا أو لأن SVG الأصلي فيه تفاصيل دقيقة. أعد التحويل بمقياس أكبر، مثل 4x بدل 1x."}];
